/* @lc app=leetcode id=3495 lang=kotlin */ class Solution { fun st(r: Long): Int = (1..16).count { (1L shl (2 * (it - 1))) <= r } fun minOperations(queries: Array<IntArray>): Long = queries.sumOf { (l, r) -> (1..16).sumOf { k -> k.toLong() * maxOf(0L, minOf(r.toLong(), (1L shl (2 * k)) - 1) - maxOf(l.toLong(), 1L shl (2 * (k - 1))) + 1) }.let { S -> maxOf((S + 1) / 2, st(r.toLong()).toLong()) } } }